package se233.vector_magic.service;

import javafx.scene.Group;
import javafx.scene.paint.Color;
import javafx.scene.shape.SVGPath;

import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Parses SVG path strings generated by VectorizationService
 * and constructs native JavaFX SVGPath nodes inside a Group.
 * Eliminates external browser/WebView dependencies and ensures cross-JDK compatibility.
 */
public class SvgViewRenderer {

    private static final Pattern PATH_PATTERN = Pattern.compile("<path\\s+([^>]+)/>", Pattern.CASE_INSENSITIVE);
    private static final Pattern D_PATTERN = Pattern.compile("d=\"([^\"]+)\"");
    private static final Pattern FILL_PATTERN = Pattern.compile("fill=\"([^\"]+)\"");
    private static final Pattern OPACITY_PATTERN = Pattern.compile("opacity=\"([^\"]+)\"");
    private static final Pattern RGB_PATTERN = Pattern.compile("rgb\\((\\d+)\\s*,\\s*(\\d+)\\s*,\\s*(\\d+)\\)");

    /**
     * Converts an SVG XML string into a native JavaFX Group of SVGPath shapes.
     *
     * @param svgContent The SVG markup string
     * @return JavaFX Group containing the rendered vector paths
     */
    public static Group renderSvgToGroup(String svgContent) {
        Group group = new Group();
        if (svgContent == null || svgContent.isEmpty()) {
            return group;
        }

        Matcher pathMatcher = PATH_PATTERN.matcher(svgContent);
        while (pathMatcher.find()) {
            String pathAttrs = pathMatcher.group(1);

            Matcher dMatcher = D_PATTERN.matcher(pathAttrs);
            if (!dMatcher.find()) continue;
            String d = dMatcher.group(1);

            SVGPath svgPath = new SVGPath();
            svgPath.setContent(d);

            // Parse fill color
            Matcher fillMatcher = FILL_PATTERN.matcher(pathAttrs);
            if (fillMatcher.find()) {
                String fillStr = fillMatcher.group(1);
                Color fillColor = parseColor(fillStr);
                svgPath.setFill(fillColor);
                svgPath.setStroke(fillColor);
                svgPath.setStrokeWidth(0.1);
                svgPath.setStrokeLineJoin(javafx.scene.shape.StrokeLineJoin.ROUND);
            } else {
                svgPath.setFill(Color.BLACK);
            }

            // Parse opacity
            Matcher opMatcher = OPACITY_PATTERN.matcher(pathAttrs);
            if (opMatcher.find()) {
                try {
                    double opacity = Double.parseDouble(opMatcher.group(1));
                    svgPath.setOpacity(Math.max(0.0, Math.min(1.0, opacity)));
                } catch (NumberFormatException ignored) {}
            }

            group.getChildren().add(svgPath);
        }

        return group;
    }

    private static Color parseColor(String str) {
        if (str == null || str.equalsIgnoreCase("none")) {
            return Color.TRANSPARENT;
        }
        Matcher rgbMatcher = RGB_PATTERN.matcher(str);
        if (rgbMatcher.find()) {
            int r = Integer.parseInt(rgbMatcher.group(1));
            int g = Integer.parseInt(rgbMatcher.group(2));
            int b = Integer.parseInt(rgbMatcher.group(3));
            return Color.rgb(r, g, b);
        }
        try {
            return Color.web(str);
        } catch (Exception e) {
            return Color.BLACK;
        }
    }
}
